// Task represents a unit of work to be executed by the worker pool.
// The Execute method is called by a worker goroutine. It receives a context
// that is canceled when the pool is shutting down or when the task's deadline
// expires. The task should respect context cancellation and return promptly.
type Task interface {
	Execute(ctx context.Context) (interface{}, error)
}

// TaskFunc is a convenience type that allows a function to implement Task.
type TaskFunc func(ctx context.Context) (interface{}, error)

// Execute implements the Task interface.
func (f TaskFunc) Execute(ctx context.Context) (interface{}, error) {
	return f(ctx)
}

// Result holds the outcome of a task execution.
type Result struct {
	// Value is the value returned by the task, if any.
	Value interface{}
	// Err is the error returned by the task, if any.
	Err error
	// Panic is the recovered panic value, if the task panicked.
	Panic interface{}
	// CompletedAt is the time when the task finished.
	CompletedAt time.Time
}

