//   - At most `capacity` tasks are executing concurrently.
//   - At most `queueSize` tasks are waiting in the queue.
//   - Tasks are executed in FIFO order.
//   - Panics in tasks are recovered and reported in Result.Panic.
//   - No goroutine leaks: all worker goroutines exit when the pool is closed.
//   - No data races: all shared state is protected by mutexes or channels.
type Pool struct {
	capacity   int
	queueSize  int
	queue      chan Task
	results    chan Result
	workers    sync.WaitGroup
	closed     atomic.Bool
	closeOnce  sync.Once
	shutdownCh chan struct{}
	wg         sync.WaitGroup
	mu         sync.Mutex
